<template>
  <div :class="`${id}-wrap`">
    <select class="custom-select" :class="id" :placeholder="placeholder">
      <option
        v-for="option in options"
        :class="`${option.value}`"
        :key="option"
        :name="option.name"
        :value="option.value"
      >
        {{ option.name }}
      </option>
    </select>
  </div>
</template>

<script>
import $ from "jquery";

export default {
  name: "CustomSelect",
  emits: ["input", "update:modelValue"],
  props: {
    id: {
      type: String,
      required: true,
    },
    placeholder: {
      type: String,
      default: "Select an option",
    },
    options: {
      type: Array,
      required: true,
    },
    default: {
      type: Object,
    },
    modelValue: {},
  },
  data() {
    return {
      selected: "",
    };
  },
  watch: {
    modelValue(newVal) {
      this.selected = newVal;
    },
  },
  methods: {
    change(text) {
      $(`.${this.id}-custom-option`)
        .parents(`.${this.id}`)
        .find(`.${this.id}-trigger`)
        .text(text);

      $(`.${this.id}-custom-option`).each(function () {
        if ($(this).text() === text) {
          $(this)
            .parents(".custom-options")
            .find(".custom-option")
            .removeClass("selection");
          $(this).addClass("selection");
        }
      });
    },
  },
  mounted() {
    let oldelements = $(`.${this.id}`).clone();
    $(`.${this.id}`).remove();
    $(`.${this.id}-wrap`).append(oldelements);

    let that = this;
    $(`.${that.id}`).each(function () {
      var classes = $(this).attr("class");
      var template = '<div class="' + classes + '">';
      template +=
        '<span class="' +
        that.id +
        '-trigger custom-select-trigger">' +
        $(this).attr("placeholder") +
        "</span>";
      template += '<div class="custom-options">';
      $(this)
        .find("option")
        .each(function () {
          template +=
            '<span class="' +
            that.id +
            "-custom-option custom-option " +
            $(this).attr("class") +
            '" data-value="' +
            $(this).attr("value") +
            '" data-name="' +
            $(this).attr("name") +
            '">' +
            $(this).html() +
            "</span>";
        });
      template += "</div></div>";

      $(this).wrap(
        '<div class="' + that.id + '-wrapper custom-select-wrapper"></div>'
      );
      $(this).hide();
      $(this).after(template);
    });
    $(`.${that.id}-custom-option:first-of-type`).hover(
      function () {
        $(this).parents(".custom-options").addClass("option-hover");
      },
      function () {
        $(this).parents(".custom-options").removeClass("option-hover");
      }
    );
    $(`.${that.id}-trigger`).on("click", function () {
      $("html").one("click", function () {
        $(`.${that.id}`).removeClass("opened");
      });
      $(this).parents(`.${that.id}`).toggleClass("opened");
      event.stopPropagation();
    });
    $(`.${that.id}-custom-option`).on("click", function () {
      $(this)
        .parents(`.${that.id}-wrapper`)
        .find("select")
        .val($(this).data("value"));
      $(this)
        .parents(".custom-options")
        .find(".custom-option")
        .removeClass("selection");
      $(this).addClass("selection");
      $(this).parents(`.${that.id}`).removeClass("opened");
      $(this)
        .parents(`.${that.id}`)
        .find(`.${that.id}-trigger`)
        .text($(this).text());
      let returnObject = {
        name: $(this)[0].dataset.name,
        value: $(this)[0].dataset.value,
      };
      that.selected = returnObject;
      that.$emit("input", returnObject);
      that.$emit("update:modelValue", returnObject);
    });
    if (that.default) {
      $(`.${that.id}-custom-option`).each(function () {
        if ($(this).text() === that.default.name) {
          $(this)
            .parents(".custom-options")
            .find(".custom-option")
            .removeClass("selection");
          $(this).addClass("selection");
          $(this)
            .parents(`.${that.id}`)
            .find(`.${that.id}-trigger`)
            .text($(this).text());
        }
      });
    } else {
      $(`.${that.id}-trigger`).text(that.options[0].name);
      $(`.${that.options[0].value}`).addClass("selection");
      that.selected = that.options[0].value;
    }
  },
};
</script>

<style lang="scss" scoped>
label {
  width: 100%;
  float: left;
  margin-left: 25px;
  margin-bottom: 10px;
}
select {
  z-index: 3;
  float: left;
}
</style>

<style lang="scss">
/* INPUT SELECT OPTION */
.center {
  position: absolute;
  display: inline-block;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
/** Custom Select **/
.custom-select-wrapper {
  position: relative;
  display: inline-block;
  user-select: none;
  cursor: pointer;
}
.custom-select-wrapper select {
  display: none;
}
.custom-select {
  position: relative;
  display: inline-block;
}
.custom-select-trigger {
  position: relative;
  display: block;
  min-width: 200px;
  padding: 0 104px 0 25px;
  font-weight: 100;
  color: $white-text;
  line-height: 50px;
  background-color: darken($foreground, 2%);
  border-radius: $radius-sm;
  border: 1.5px solid lighten($foreground, 15%);
  cursor: pointer;
  transition: all 0.2s ease-in-out;
  font-weight: 400;
}
.custom-select-trigger:before {
  position: absolute;
  display: block;
  content: "";
  width: 1px;
  height: 100%;
  top: 3px;
  right: 50px;
  margin-top: -3px;
  border-right: 1.5px solid lighten($foreground, 15%);
  transition: all 0.35s ease-out;
  transform-origin: 50% 0;
}
.custom-select-trigger:hover {
  border-color: $blue;
}

.custom-select-trigger:after {
  position: absolute;
  display: block;
  content: "";
  width: 10px;
  height: 10px;
  top: 50%;
  right: 20px;
  margin-top: -3px;
  border-bottom: 2px solid $white-text;
  border-right: 2px solid $white-text;
  transform: rotate(45deg) translateY(-50%);
  transition: all 0.35s ease-out;
  transform-origin: 50% 0;
}
.custom-select.opened .custom-select-trigger:after {
  margin-top: 3px;
  transform: rotate(-135deg) translateY(-50%);
}
.custom-options {
  z-index: 999;
  position: absolute;
  display: block;
  top: 100%;
  left: 0%;
  right: 0;
  width: 100%;

  margin: 10px 0;
  border-radius: $radius-sm;
  box-sizing: border-box;
  /*  box-shadow: 0 2px 1px rgba(0, 0, 0, .1); */

  background-color: darken($foreground, 2%);
  transition: all 0.2s ease-in-out;

  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(-15px);
  border: 0;
}
.custom-select.opened .custom-options {
  opacity: 1;
  visibility: visible;
  pointer-events: all;
  transform: translateY(-8px);
}
.option-hover:before {
  background: #f9f9f9;
}
.custom-option {
  position: relative;
  display: block;
  padding: 0 22px;
  font-weight: 400;
  color: $white-text;
  line-height: 47px;
  cursor: pointer;
  transition: all 0.05s ease-in-out;
}
.custom-option:first-of-type {
  border-radius: $radius-sm $radius-sm 0 0;

  border-top-right-radius: $radius-sm;
  border-top-left-radius: $radius-sm;
}
.custom-option:last-of-type {
  border-bottom: 0;
  border-radius: 0 0 4px 4px;
  border-bottom-right-radius: 5px;
  border-bottom-left-radius: 5px;
}
.custom-option:hover,
.custom-option.selection {
  color: $blue;
  background-color: rgba($blue, 0.3);
}
</style>
