<template>
  <div
    class="chat-wrap"
    style="width: 100vw; height: 100vh; position: relative"
    :style="{ opacity: settings.opacity }"
    v-show="enabled"
  >
    <div class="chat">
      <chat-input
        v-model:input="input"
        v-model:isOpenAutoComplete="isOpenAutoComplete"
        :foundCommands="foundCommands"
        @sendMsg="sendChat"
        @historyUp="historyUp"
        @historyDown="historyDown"
      />
      <div id="chat-messages" class="messages" tabindex="-1">
        <chat-message v-for="msg in messages" :key="msg" :message="msg" />
      </div>
    </div>
  </div>
</template>

<script>
import ChatMessage from "./ChatMessage";
import ChatInput from "./ChatInput";
import $ from "jquery";
import interact from "interactjs";

export default {
  name: "chat",
  components: { ChatInput, ChatMessage },
  props: {
    devMode: Boolean,
  },
  data() {
    return {
      enabled: false,
      active: false,
      settings: {
        opacity: 1,
        autoScroll: true,
      },
      args: [],
      isOpenAutoComplete: false,
      input: "",
      foundCommands: [],
      commands: [
        {
          CommandText: "dbgcreatepickup",
          Parameters: ["model", "r", "g", "b", "range", "intensity", "shadow"],
          Admin: 1,
        },
        {
          CommandText: "dbgcreatepickup1",
          Parameters: ["model", "r", "g", "b", "range", "intensity", "shadow"],
          Admin: 1,
        },
        {
          CommandText: "dbgcreatepickup2",
          Parameters: ["model"],
          Admin: 1,
        },
        {
          CommandText: "sus",
          Parameters: ["model", "r", "g", "b", "range", "intensity", "shadow"],
          Admin: 1,
        },
      ],
      messages: [
        "!{#A9C4E4}Connected to !{#ffae00}Race !{#FFFFFF}'n !{#0097ff}Chase!{#A9C4E4}.",
      ],
      history: [],
      historyIndex: 0,
    };
  },
  mounted() {
    interact(".chat")
      .draggable({
        inertia: true,
        modifiers: [
          interact.modifiers.restrictRect({
            restriction: "parent",
            endOnly: true,
          }),
        ],
        autoScroll: true,
        listeners: {
          move: dragMoveListener,
        },
      })
      .resizable({
        // resize from all edges and corners
        edges: { left: false, right: true, bottom: false, top: true },

        listeners: {
          move(event) {
            let target = event.target;
            let x = parseFloat(target.getAttribute("data-x")) || 0;
            let y = parseFloat(target.getAttribute("data-y")) || 0;

            // update the element's style
            target.style.width = event.rect.width + "px";
            target.style.height = event.rect.height + "px";

            // translate when resizing from top or left edges
            x += event.deltaRect.left;
            y += event.deltaRect.top;

            target.style.transform = "translate(" + x + "px," + y + "px)";

            target.setAttribute("data-x", x);
            target.setAttribute("data-y", y);
          },
        },
        modifiers: [
          // keep the edges inside the parent
          interact.modifiers.restrictEdges({
            outer: "parent",
          }),

          // minimum size
          interact.modifiers.restrictSize({
            min: { width: 100, height: 50 },
          }),
        ],

        inertia: true,
      });

    function dragMoveListener(event) {
      let target = event.target;
      let x = (parseFloat(target.getAttribute("data-x")) || 0) + event.dx;
      let y = (parseFloat(target.getAttribute("data-y")) || 0) + event.dy;
      target.style.transform = "translate(" + x + "px, " + y + "px)";
      target.setAttribute("data-x", x);
      target.setAttribute("data-y", y);
    }

    window.dragMoveListener = dragMoveListener;

    document.addEventListener("scroll", this.handleScroll);
  },
  methods: {
    handleScroll() {
      if (this.active) this.settings.autoScroll = false;
    },
    historyUp() {
      if (this.history.length < 1) return;
      this.historyIndex =
        this.historyIndex + 1 > this.history.length
          ? 1
          : (this.historyIndex += 1);
      this.input = this.history[this.history.length - this.historyIndex];
    },
    historyDown() {
      if (this.history.length < 1) return;
      this.historyIndex =
        this.historyIndex - 1 <= 0
          ? this.history.length
          : (this.historyIndex -= 1);
      this.input = this.history[this.history.length - this.historyIndex];
    },
    sendChat() {
      // eslint-disable-next-line
      if (!this.devMode) mp.trigger("onChatPressEnter");
      this.settings.autoScroll = true;

      if (this.input.length < 1) return;
      if (this.input.startsWith("/")) {
        // eslint-disable-next-line
        if (!this.devMode) mp.invoke("command", this.input.substr(1));
      } else {
        // eslint-disable-next-line
        if (!this.devMode) mp.invoke("chatMessage", this.input);
        else this.messages.push(this.input);
      }
      this.history.push(this.input);
      this.historyIndex = 0;
      this.input = "";

      this.scrollToBottomMsg();
    },
    scrollToBottomMsg() {
      setTimeout(() => {
        document
          .getElementById("chat-messages")
          .scrollTo(0, document.getElementById("chat-messages").scrollHeight);
      }, 200);
    },
  },
  watch: {
    messages: {
      handler() {
        if (this.settings.autoScroll) this.scrollToBottomMsg();
      },
      deep: true,
    },
    active(val) {
      let input = $("#chat-input");
      if (val) {
        input.focus();
      } else {
        input.blur();
        this.isOpenAutoComplete = false;
      }
    },
    input() {
      let command = this.input.split(" ")[0];
      if (!command || !command.startsWith("/"))
        return (this.isOpenAutoComplete = false);
      const foundCommands = this.commands.filter((c) =>
        c.CommandText.toLowerCase().startsWith(
          command.toLowerCase().replace("/", "")
        )
      );
      if (this.input.length < 2) return (this.isOpenAutoComplete = false);
      this.foundCommands = foundCommands.slice(0, 5);
      this.isOpenAutoComplete = this.foundCommands.length > 0;
    },
  },
};
</script>

<style lang="scss" scoped>
.chat {
  background: rgba($background, 0.5);
  width: 500px;
  height: 250px;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  flex-direction: column-reverse;
  overflow: visible;
  position: absolute;
  top: 5px;
  left: 5px;
  direction: rtl;
  border-radius: 2px;

  .messages {
    width: 100%;
    max-height: 100%;
    overflow-y: auto;
    padding: 5px;

    div {
      direction: ltr;
    }
  }
}

/* Track */
::-webkit-scrollbar-track {
  background: rgba($blue, 0.2);
  border-radius: 2px 0 0 0 !important;
}

/* Handle */
::-webkit-scrollbar-thumb {
  background: rgba($blue, 0.5);
  border-radius: 2px 0 0 0 !important;
}

/* Handle on hover */
::-webkit-scrollbar-thumb:hover {
  background: rgba(lighten($blue, 5%), 0.5);
}
</style>
