<template>
  <HudCard class="mt-1 flex items-center" v-if="enabled">
    <span class="title mr-2">{{ title }}</span
    ><span class="flex items-center">
      <i class="fa-solid fa-stopwatch text-lg mr-1"></i>{{ formatted }}</span
    >
  </HudCard>
</template>

<script>
import HudCard from "../../components/HudCard.vue";
export default {
  name: "GameProgress",
  data() {
    return {
      enabled: false,
      title: "Time Left",
      time: 0,
    };
  },
  methods: {
    format(time) {
      var mins = ~~((time % 3600) / 60);
      var secs = ~~time % 60;
      var ret = "";
      ret += "" + mins + ":" + (secs < 10 ? "0" : "");
      ret += "" + secs;
      return ret;
    },
  },
  computed: {
    formatted() {
      return this.format(this.time);
    },
  },
  components: { HudCard },
};
</script>

